body.script:
//
// ===== IMPORTAR TITULOS (.json) — roda ANTES do script principal =====
(function(){
  var STORAGE_KEY = 'voicekar_imported_titles';
  var list = document.getElementById('videoList');
  if (!list) { return; }

  function buildFromTitles(titles){
    list.innerHTML = '';
    titles.forEach(function(t){
      var li = document.createElement('li');
      li.setAttribute('data-tags', '');
      li.style.borderRightColor = '#2ecc71';
      var chk = document.createElement('input');
      chk.className = 'chk';
      chk.type = 'checkbox';
      var span = document.createElement('span');
      span.className = 'item-text';
      span.textContent = String(t);
      li.appendChild(chk);
      li.appendChild(span);
      list.appendChild(li);
    });
  }

  // Se ja existe uma lista importada salva, reconstroi a lista ANTES do
  // script principal inicializar (assim busca/selecao/contagem funcionam).
  try {
    var raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      var arr = JSON.parse(raw);
      if (Array.isArray(arr) && arr.length) { buildFromTitles(arr); }
    }
  } catch (e) {}

  // Botao importar
  var btnImport  = document.getElementById('btnImport');
  var importFile = document.getElementById('importFile');
  if (btnImport && importFile) {
    btnImport.addEventListener('click', function(){ importFile.click(); });
    importFile.addEventListener('change', function(){
      var file = this.files && this.files[0];
      this.value = '';
      if (!file) { return; }
      var reader = new FileReader();
      reader.onload = function(){
        try {
          var data = JSON.parse(reader.result);
          if (!Array.isArray(data)) { throw new Error('formato'); }
          var titles = data
            .map(function(x){ return String(x); })
            .filter(function(s){ return s.trim() !== ''; });
          if (!titles.length) { throw new Error('vazio'); }
          localStorage.setItem(STORAGE_KEY, JSON.stringify(titles));
          location.reload();
        } catch (err) {
          alert('Arquivo JSON invalido. Envie um arquivo com uma lista de titulos.');
        }
      };
      reader.readAsText(file);
    });
  }
})();
//

//
(function(){
  var input        = document.getElementById('searchInput');
  var btnClear     = document.getElementById('btnClear');
  var btnGenList   = document.getElementById('btnGenList');
  var genBadge     = document.getElementById('genBadge');
  var list         = document.getElementById('videoList');
  var noResults    = document.getElementById('noResults');
  var countVisible = document.getElementById('countVisible');
  var countTotal   = document.getElementById('countTotal');
  var selInfo      = document.getElementById('selInfo');
  if (!input || !list) { return; }

  var allItems = list.querySelectorAll('li');
  var total = allItems.length;
  countTotal.textContent = total;
  countVisible.textContent = total;

  /* ---------- BUSCA ---------- */
  input.addEventListener('input', function(){
    btnClear.classList.toggle('show', this.value.length > 0);
    filter();
  });

  btnClear.addEventListener('click', function(){
    input.value = '';
    btnClear.classList.remove('show');
    filter();
    input.focus();
  });

  function filter(){
    var q = input.value.toLowerCase().trim();
    var visible = 0;
    Array.prototype.forEach.call(allItems, function(li){
      var text = itemTitle(li).toLowerCase();
      var tags = (li.getAttribute('data-tags') || '').toLowerCase();
      var match = !q || text.indexOf(q) !== -1 || tags.indexOf(q) !== -1;
      li.classList.toggle('hidden', !match);
      if (match) { visible++; }
    });
    countVisible.textContent = visible;
    noResults.classList.toggle('show', visible === 0);
  }

  /* ---------- TITULO DO ITEM ---------- */
  function itemTitle(li){
    var span = li.querySelector('.item-text');
    return ((span ? span.textContent : li.textContent) || '').replace(/\s+/g, ' ').trim();
  }

  /* ---------- SELECAO ---------- */
  Array.prototype.forEach.call(allItems, function(li){
    var chk = li.querySelector('input.chk');
    if (!chk) { return; }

    chk.addEventListener('change', function(){
      li.classList.toggle('checked', chk.checked);
      updateSelection();
    });

    /* clicar no texto tambem marca/desmarca */
    var span = li.querySelector('.item-text');
    if (span) {
      span.addEventListener('click', function(ev){
        if (ev.target.tagName === 'A') { return; }
        chk.checked = !chk.checked;
        li.classList.toggle('checked', chk.checked);
        updateSelection();
      });
    }
  });

  function getSelected(){
    var out = [];
    Array.prototype.forEach.call(allItems, function(li){
      var chk = li.querySelector('input.chk');
      if (chk && chk.checked) {
        out.push({ title: itemTitle(li), tags: li.getAttribute('data-tags') || '' });
      }
    });
    return out;
  }

  function updateSelection(){
    var n = getSelected().length;
    genBadge.textContent = n;
    btnGenList.classList.toggle('has-sel', n > 0);
    selInfo.textContent = n > 0 ? ('\u2014 ' + n + ' selecionado' + (n > 1 ? 's' : '')) : '';
  }

  /* ---------- ESCAPE ---------- */
  function esc(s){
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  /* ---------- GERAR LISTA EM NOVA ABA ---------- */
  btnGenList.addEventListener('click', function(){
    var sel = getSelected();
    if (sel.length === 0) {
      alert('Selecione ao menos um item para gerar a lista.');
      return;
    }

    var d = new Date();
    var stamp = d.toLocaleDateString('pt-BR') + ' ' + d.toLocaleTimeString('pt-BR');

    var rows = '';
    for (var i = 0; i < sel.length; i++) {
      rows += '<tr><td class="n">' + (i + 1) + '</td><td>' + esc(sel[i].title) +
              '</td><td class="tg">' + esc(sel[i].tags) + '</td></tr>';
    }

    var css = 'body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;' +
              'background:#1a1a1a;color:#d0d0d0;margin:0;padding:24px;font-size:16px;' +
              '-webkit-text-size-adjust:100%}' +
              'h1{font-size:22px;color:#e0e0e0;margin:0 0 6px}' +
              '.meta{font-size:14px;color:#888;margin-bottom:18px}' +
              'table{width:100%;border-collapse:collapse;background:#222;border-radius:8px;overflow:hidden}' +
              'th,td{padding:11px 12px;text-align:left;font-size:16px;border-bottom:1px solid #303030;' +
              'word-break:break-word}' +
              'th{background:#151515;color:#999;font-size:13px;text-transform:uppercase;letter-spacing:.5px}' +
              'tr:last-child td{border-bottom:none}' +
              'td.n{width:46px;color:#777;text-align:right}' +
              'td.tg{width:230px;color:#2ecc71;font-size:13px}' +
              '@media (max-width:700px){body{padding:12px;font-size:18px}' +
              'h1{font-size:24px}.meta{font-size:15px}' +
              'th,td{font-size:18px;padding:12px 8px}' +
              'th{font-size:14px}td.n{width:38px}' +
              'td.tg{display:none}th:nth-child(3){display:none}}' +
              '@media print{body{background:#fff;color:#000;padding:0}table{background:#fff}' +
              'th{background:#eee;color:#000}td.tg{color:#555}}';

    var html = '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8">' +
               '<meta name="viewport" content="width=device-width, initial-scale=1.0">' +
               '<title>Lista Gerada \u2014 ' + sel.length + ' item(ns)</title>' +
               '<style>' + css + '</style></head><body>' +
               '<h1>\uD83D\uDCCB Lista Gerada</h1>' +
               '<div class="meta">' + sel.length + ' item(ns) selecionado(s) \u2014 ' + esc(stamp) + '</div>' +
               '<table><thead><tr><th>#</th><th>T\u00edtulo</th><th>Tags</th></tr></thead>' +
               '<tbody>' + rows + '</tbody></table>' +
               '</body></html>';

    /* ---- abre em janela POPUP ---- */
    var pw = Math.min(760, Math.max(480, screen.availWidth - 120));
    var ph = Math.min(680, Math.max(420, screen.availHeight - 140));
    var px = Math.round((screen.availWidth  - pw) / 2);
    var py = Math.round((screen.availHeight - ph) / 2);
    var feats = 'popup=yes,width=' + pw + ',height=' + ph + ',left=' + px + ',top=' + py +
                ',scrollbars=yes,resizable=yes,menubar=no,toolbar=no,location=no,status=no';

    /* Abre a partir de um Blob (documento real) para o navegador respeitar
       a meta viewport. Escrever com document.write faz vários navegadores
       de celular renderizarem em 980px e reduzirem a fonte. */
    var blobUrl = null;
    try {
      if (window.Blob && window.URL && window.URL.createObjectURL) {
        blobUrl = URL.createObjectURL(new Blob([html], { type: 'text/html;charset=utf-8' }));
      }
    } catch (e) { blobUrl = null; }

    var win = window.open(blobUrl || '', 'listaGerada', feats);
    if (!win) {
      if (blobUrl) { URL.revokeObjectURL(blobUrl); }
      alert('O navegador bloqueou a janela popup. Permita pop-ups para este site e tente novamente.');
      return;
    }

    if (!blobUrl) {
      win.document.open();
      win.document.write(html);
      win.document.close();
      /* reforca o viewport caso o navegador ignore a meta tag inicial */
      try {
        var mv = win.document.querySelector('meta[name="viewport"]');
        if (!mv) {
          mv = win.document.createElement('meta');
          mv.setAttribute('name', 'viewport');
          win.document.head.appendChild(mv);
        }
        mv.setAttribute('content', 'width=device-width, initial-scale=1.0');
      } catch (e2) {}
    } else {
      setTimeout(function(){ URL.revokeObjectURL(blobUrl); }, 60000);
    }

    try { win.focus(); } catch (e3) {}
  });

  filter();
  updateSelection();
})();
//
